package tv.vela.launcher;

import android.app.*;
import android.content.*;
import android.graphics.Bitmap;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.lang.reflect.*;
import java.util.*;
import java.util.concurrent.*;
import org.json.JSONObject;

/** Real Home navigation, isolated demo accounts, native remote input and no system configuration writes. */
public final class AndroidIntegratedSettingsTest extends Instrumentation {
    private HomeActivity activity;
    private volatile HomeActivity created;
    private String phase="setup";
    private int separateScreens;
    public static final class Home extends HomeActivity {@Override PlexClient createPlexClient(){return new DemoPlex(this);}}
    static final class DemoPlex extends PlexClient {
        DemoPlex(Context c){super(c);}
        @Override JSONObject createPin()throws Exception{return new JSONObject().put("id",1).put("code","DEMO").put("expiresIn",900);}
        @Override boolean checkPin(long id,String code){return false;}
    }
    @Override public Activity newActivity(ClassLoader cl,String name,Intent intent)throws InstantiationException,IllegalAccessException,ClassNotFoundException{
        if(name.equals(HomeActivity.class.getName())){created=new Home();return created;}
        if(name.equals(SettingsActivity.class.getName())||name.equals(UpdatesActivity.class.getName())||name.equals(PlexLinkActivity.class.getName())||name.equals(JellyfinLinkActivity.class.getName())||name.equals(XtreamLinkActivity.class.getName())||name.equals(SetupActivity.class.getName())||name.equals(LiveTvActivity.class.getName()))separateScreens++;
        return super.newActivity(cl,name,intent);
    }
    Object field(Object target,String name)throws Exception{for(Class<?> type=target.getClass();type!=null;type=type.getSuperclass())try{Field f=type.getDeclaredField(name);f.setAccessible(true);return f.get(target);}catch(NoSuchFieldException next){}throw new NoSuchFieldException(name);}
    void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    void ui(Runnable action){runOnMainSync(action);waitForIdleSync();}
    interface Ready{boolean ready()throws Exception;}
    void await(Ready ready,String why)throws Exception{long end=SystemClock.elapsedRealtime()+15000;while(SystemClock.elapsedRealtime()<end){waitForIdleSync();if(ready.ready())return;Thread.sleep(100);}throw new AssertionError(why);}
    void click(View view){ui(view::requestFocus);sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_CENTER);waitForIdleSync();}
    void key(int code){sendKeyDownUpSync(code);waitForIdleSync();}
    HomeScreenHost panels(Object home)throws Exception{return (HomeScreenHost)field(home,"panels");}
    List<View> rows(HomeScreenHost host)throws Exception{return (List<View>)field(field(host.screen,"view"),"rows");}
    void capture(String name)throws Exception{Thread.sleep(350);Bitmap shot=getUiAutomation().takeScreenshot();check(shot!=null&&shot.getWidth()==3840&&shot.getHeight()==2160,"Native 4K capture required");try(OutputStream out=new FileOutputStream(new File(getTargetContext().getExternalFilesDir(null),"integrated-"+name+".png"))){shot.compress(Bitmap.CompressFormat.PNG,100,out);}finally{shot.recycle();}}
    void restore(SharedPreferences prefs,Map<String,?> saved){SharedPreferences.Editor e=prefs.edit().clear();for(Map.Entry<String,?> entry:saved.entrySet()){Object v=entry.getValue();String k=entry.getKey();if(v instanceof String)e.putString(k,(String)v);else if(v instanceof Integer)e.putInt(k,(Integer)v);else if(v instanceof Long)e.putLong(k,(Long)v);else if(v instanceof Boolean)e.putBoolean(k,(Boolean)v);else if(v instanceof Float)e.putFloat(k,(Float)v);else if(v instanceof Set)e.putStringSet(k,new HashSet<>((Set<String>)v));}e.commit();}
    public void onCreate(Bundle args){super.onCreate(args);start();}
    public void onStart(){Bundle result=new Bundle();Context c=getTargetContext();Map<SharedPreferences,Map<String,?>> saved=new LinkedHashMap<>();List<ActivityMonitor> monitors=new ArrayList<>();try{
        check(Build.FINGERPRINT.contains("generic")||Build.MODEL.contains("sdk"),"Owned clean emulator required");check(!new PlexClient(c).connected()&&!new JellyfinClient(c).connected()&&!new XtreamClient(c).connected(),"Personal accounts must not be used");
        for(SharedPreferences p:new SharedPreferences[]{Personalization.prefs(c),SidebarApps.prefs(c),Visuals.prefs(c),AmbientPrefs.get(c),AmbientWeather.prefs(c),Updates.prefs(c),LiveTvData.prefs(c)})saved.put(p,new HashMap<>(p.getAll()));
        Personalization.complete(c);Updates.prefs(c).edit().putBoolean("automatic",false).putBoolean("download",false).commit();AmbientWeather.select(c,new AmbientWeather.Place("Reikiavik · Demo","",64.15,-21.94,"Atlantic/Reykjavik"));
        List<String> apps=new ArrayList<>();apps.add(SidebarApps.YOUTUBE);for(String p:SidebarApps.slots(c))if(!p.equals(SidebarApps.YOUTUBE)&&SidebarApps.launchable(c,p)&&apps.size()<3)apps.add(p);SidebarApps.prefs(c).edit().putString("slots",new org.json.JSONArray(apps).toString()).commit();
        activity=(HomeActivity)startActivitySync(new Intent(c,HomeActivity.class).putExtra("velaEntry","settings").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));await(activity::hasWindowFocus,"Home window missing");CinemaHomeView home=(CinemaHomeView)field(activity,"home");Object sidebar=field(home,"sidebar"),header=field(home,"headerStatus");List<View> side=(List<View>)field(home,"sideButtons");
        phase="pinned-apps";List<View> pinned=(List<View>)field(home,"appButtons");
        for(int i=0;i<apps.size();i++){Intent intent=HomeApps.launchIntent(c.getPackageManager(),apps.get(i));check(intent!=null&&intent.getComponent()!=null,"Fixture application missing");ActivityMonitor monitor=addMonitor(intent.getComponent().getClassName(),new ActivityResult(Activity.RESULT_CANCELED,null),true);monitors.add(monitor);click(pinned.get(i));check(monitor.getHits()==1,"OK did not directly launch the pinned application");removeMonitor(monitor);}
        ui(()->pinned.get(0).requestFocus());key(KeyEvent.KEYCODE_DPAD_RIGHT);check((Integer)field(home,"filter")==3&&panels(home)==null,"Right did not keep YouTube content inside Home");check(activity.hasWindowFocus(),"YouTube preview opened another application");
        phase="settings";click(side.get(7));HomeScreenHost host=panels(home);check(host!=null&&host.screen instanceof SettingsScreen,"Settings did not mount in Home");check(field(home,"sidebar")==sidebar&&field(home,"headerStatus")==header&&field(home,"heroBitmap")==null,"Settings replaced shared chrome or retained hidden artwork");check(activity.getCurrentFocus()!=null&&activity.getCurrentFocus().isShown(),"Settings content has no visible focus");capture("01-ajustes");
        phase="settings-shortcuts";ui(()->pinned.get(0).requestFocus());sendKeySync(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_CENTER));Thread.sleep(ViewConfiguration.getLongPressTimeout()+200);sendKeySync(new KeyEvent(KeyEvent.ACTION_UP,KeyEvent.KEYCODE_DPAD_CENTER));waitForIdleSync();check(field(home,"menuPackage")!=null,"Long OK did not open app actions inside Settings");key(KeyEvent.KEYCODE_BACK);check(field(home,"menuPackage")==null&&host.screen instanceof SettingsScreen,"Shortcut Back changed the settings page");ui(()->side.get(7).requestFocus());key(KeyEvent.KEYCODE_DPAD_RIGHT);
        phase="inline-preview";AmbientPrefs.get(c).edit().putString("style","plex").commit();click(rows(host).get(1));SettingsScreen previewScreen=(SettingsScreen)host.screen;click(rows(host).get(1));check(field(previewScreen,"preview")!=null&&host.fullscreen()&&((View)sidebar).getVisibility()==View.GONE&&((View)header).getVisibility()==View.GONE,"Screensaver preview did not use the Home host");key(KeyEvent.KEYCODE_BACK);check(field(previewScreen,"preview")==null&&!host.fullscreen()&&((View)sidebar).getVisibility()==View.VISIBLE,"Preview did not restore shared navigation");key(KeyEvent.KEYCODE_BACK);
        SettingsScreen initial=(SettingsScreen)host.screen;click(rows(host).get(6));Object settingsView=field(host.screen,"view");check((Integer)field(settingsView,"page")==2,"Appearance page missing: "+field(settingsView,"page"));click(((List<View>)field(settingsView,"rows")).get(3));check((Integer)field(settingsView,"page")==17,"Appearance details missing");capture("02-apariencia");
        click(((List<View>)field(settingsView,"rows")).get(0));click(((List<View>)field(settingsView,"rows")).get(2));check(Appearance.colorIndex(c)==2,"Accent did not persist");ui(()->Appearance.set(c,"color",0));key(KeyEvent.KEYCODE_BACK);key(KeyEvent.KEYCODE_BACK);key(KeyEvent.KEYCODE_BACK);check((Integer)field(settingsView,"page")==0,"Back did not return through settings pages");
        phase="updates";click(rows(host).get(7));settingsView=field(host.screen,"view");click(((List<View>)field(settingsView,"rows")).get(5));check(host.screen instanceof UpdatesScreen,"Updates opened outside Home");FrameLayout updateStage=(FrameLayout)field(host.screen,"stage");check(updateStage.getChildAt(0).getVisibility()==View.GONE&&updateStage.getChildAt(1).getVisibility()==View.GONE&&updateStage.getChildAt(2).getVisibility()==View.GONE,"Standalone update background or duplicate heading remained visible");check(((ExecutorService)field(field(initial,"view"),"io")).isShutdown(),"Hidden Settings worker retained");capture("03-actualizaciones");VelaScreen updates=host.screen;key(KeyEvent.KEYCODE_BACK);check(host.screen instanceof SettingsScreen,"Back did not return from Updates");check(!(Boolean)field(updates,"active"),"Updates remained active after exit");
        phase="accounts";key(KeyEvent.KEYCODE_BACK);click(rows(host).get(3));settingsView=field(host.screen,"view");check((Integer)field(settingsView,"page")==14,"Account settings missing");capture("04-cuentas");click(((List<View>)field(settingsView,"rows")).get(0));settingsView=field(host.screen,"view");click(((List<View>)field(settingsView,"rows")).get(0));check(host.screen instanceof PlexLinkScreen,"Plex linking opened a separate activity");PlexLinkScreen linked=(PlexLinkScreen)host.screen;await(()->((TextView)field(linked,"code")).getText().toString().equals("DEMO"),"Demo Plex code not rendered");capture("05-plex");VelaScreen plex=host.screen;key(KeyEvent.KEYCODE_BACK);check(((ScheduledThreadPoolExecutor)field(plex,"io")).isShutdown(),"Plex polling worker retained");
        phase="secure-accounts";key(KeyEvent.KEYCODE_BACK);settingsView=field(host.screen,"view");click(((List<View>)field(settingsView,"rows")).get(1));check(host.screen instanceof JellyfinLinkScreen,"Jellyfin linking opened outside Home");check((activity.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_SECURE)!=0,"Jellyfin form is not protected");VelaScreen jelly=host.screen;key(KeyEvent.KEYCODE_BACK);check(((ExecutorService)field(jelly,"io")).isShutdown(),"Jellyfin worker retained");check((activity.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_SECURE)==0,"Secure flag leaked to ordinary settings");
        phase="tv-sources";click(side.get(7));host=panels(home);click(rows(host).get(4));settingsView=field(host.screen,"view");click(((List<View>)field(settingsView,"rows")).get(2));check(host.screen instanceof TvSettingsScreen,"Source settings opened a channel browser activity");capture("06-fuentes-tv");
        List<View> sourceRows=host.screen.content.getFocusables(View.FOCUS_FORWARD);click(sourceRows.get(0));check((activity.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_SECURE)!=0,"M3U fields are not protected");EditText url=(EditText)field(host.screen,"address");ui(()->url.setText("https://example.invalid/demo.m3u?token=disposable-test"));Bundle snapshot=host.save();check(snapshot.getBundle("current").getBundle("state").isEmpty()&&!snapshot.toString().contains("disposable-test"),"Private input entered saved navigation state");key(KeyEvent.KEYCODE_BACK);check(url.getText().length()==0&&(activity.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_SECURE)==0,"M3U cancellation retained input or protected the public page");sourceRows=host.screen.content.getFocusables(View.FOCUS_FORWARD);click(sourceRows.get(1));check(host.screen instanceof XtreamLinkScreen,"Xtream opened outside Home");VelaScreen xtream=host.screen;key(KeyEvent.KEYCODE_BACK);check(((ExecutorService)field(xtream,"io")).isShutdown(),"Xtream worker retained");
        phase="apps-and-inputs";click(side.get(4));host=panels(home);check(host.screen instanceof AppsScreen,"Apps did not use the shared Home section");HomeScreenHost appHost=host;await(()->field(appHost.screen,"grid")!=null&&((GridView)field(appHost.screen,"grid")).getChildCount()>0,"Application icons missing");capture("07-apps");InstalledAppsGrid grid=(InstalledAppsGrid)field(host.screen,"grid");click(side.get(5));host=panels(home);check(host.screen instanceof InputsScreen&&(Boolean)field(grid,"released"),"Input navigation retained the apps grid");capture("08-entradas");
        phase="back-and-return";key(KeyEvent.KEYCODE_BACK);check(side.get(5).hasFocus(),"Back did not focus input navigation");key(KeyEvent.KEYCODE_DPAD_RIGHT);check(!side.get(5).hasFocus(),"Right did not return to input content");click(side.get(0));check(panels(home)==null&&field(home,"sidebar")==sidebar&&field(home,"headerStatus")==header,"Return Home retained settings or replaced chrome");check(separateScreens==0,"An internal screen launched a separate activity");
        phase="tv-return";click(side.get(6));HomeLiveTvView oldTv=(HomeLiveTvView)field(home,"liveTv");check(oldTv!=null,"TV did not open");ui(()->activity.startActivity(new Intent(c,XtreamLinkActivity.class)));check(panels(home).screen instanceof XtreamLinkScreen&&((ExecutorService)field(oldTv,"io")).isShutdown(),"Opening configuration from TV retained its worker");key(KeyEvent.KEYCODE_BACK);check(panels(home)==null&&field(home,"liveTv")!=null,"Back from a TV account did not return to TV");click(side.get(0));
        phase="recreation";click(side.get(7));HomeScreenHost before=panels(home);click(rows(before).get(6));click(rows(before).get(3));VelaScreen oldScreen=before.screen;HomeActivity old=activity;ui(old::recreate);await(()->created!=old&&created.hasWindowFocus(),"Home was not recreated");activity=created;CinemaHomeView recreated=(CinemaHomeView)field(activity,"home");HomeScreenHost restored=panels(recreated);check(restored!=null&&restored.screen instanceof SettingsScreen&&(Integer)field(field(restored.screen,"view"),"page")==17,"Recreation lost the settings page");check(((ExecutorService)field(field(oldScreen,"view"),"io")).isShutdown(),"Old settings worker survived recreation");
        phase="home-button";ui(()->activity.onNewIntent(new Intent(c,HomeActivity.class).addCategory(Intent.CATEGORY_HOME)));check(panels(recreated)==null&&(Boolean)field(recreated,"active")&&(Integer)field(recreated,"filter")==0,"Home button did not resume the main page after settings");
        result.putString("result","PASS direct pinned-app OK launches, Right YouTube preview, one Home Activity/shared sidebar/header, integrated Settings/appearance/updates/Plex/Jellyfin/Xtream/M3U/EPG/apps/inputs, private form flags and input clearing, safe state, worker/grid release, Back/navigation, long-OK shortcuts inside Settings, inline preview, return to TV and restored page after real Activity recreation and Home-button return. Eight native 4K captures; no personal accounts or TV system changes.");
    }catch(Throwable failure){result.putString("phase",phase);result.putString("error",android.util.Log.getStackTraceString(failure));}finally{for(ActivityMonitor monitor:monitors)removeMonitor(monitor);if(activity!=null)ui(activity::finish);for(Map.Entry<SharedPreferences,Map<String,?>> entry:saved.entrySet())restore(entry.getKey(),entry.getValue());}finish(result.containsKey("error")?1:-1,result);}
}
